NetworkServiceAsyncWaiter::NetworkServiceAsyncWaiter(
    NetworkService* proxy) : proxy_(proxy) {}

NetworkServiceAsyncWaiter::~NetworkServiceAsyncWaiter() = default;


void NetworkServiceAsyncWaiter::GetNetworkList(
    uint32_t policy, std::optional<::blink::Vector<::network::mojom::blink::NetworkInterfacePtr>>* out_networks) {
  base::RunLoop loop;
  proxy_->GetNetworkList(
      std::move(policy),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::optional<::blink::Vector<::network::mojom::blink::NetworkInterfacePtr>>* out_networks
,
             std::optional<::blink::Vector<::network::mojom::blink::NetworkInterfacePtr>> networks) {*out_networks = std::move(networks);
            loop->Quit();
          },
          &loop,
          out_networks));
  loop.Run();
}

std::optional<::blink::Vector<::network::mojom::blink::NetworkInterfacePtr>> NetworkServiceAsyncWaiter::GetNetworkList(
    uint32_t policy) {
  std::optional<::blink::Vector<::network::mojom::blink::NetworkInterfacePtr>> async_wait_result;
  GetNetworkList(std::move(policy),&async_wait_result);
  return async_wait_result;
}

void NetworkServiceAsyncWaiter::SetTrustTokenKeyCommitments(
    const ::blink::String& raw_commitments) {
  base::RunLoop loop;
  proxy_->SetTrustTokenKeyCommitments(
      std::move(raw_commitments),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}



void NetworkServiceAsyncWaiter::ParseHeaders(
    const ::blink::KURL& url, ::network::mojom::blink::HttpResponseHeadersPtr headers, ::network::mojom::blink::ParsedHeadersPtr* out_parsed_headers) {
  base::RunLoop loop;
  proxy_->ParseHeaders(
      std::move(url),
      std::move(headers),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::network::mojom::blink::ParsedHeadersPtr* out_parsed_headers
,
             ::network::mojom::blink::ParsedHeadersPtr parsed_headers) {*out_parsed_headers = std::move(parsed_headers);
            loop->Quit();
          },
          &loop,
          out_parsed_headers));
  loop.Run();
}

::network::mojom::blink::ParsedHeadersPtr NetworkServiceAsyncWaiter::ParseHeaders(
    const ::blink::KURL& url, ::network::mojom::blink::HttpResponseHeadersPtr headers) {
  ::network::mojom::blink::ParsedHeadersPtr async_wait_result;
  ParseHeaders(std::move(url),std::move(headers),&async_wait_result);
  return async_wait_result;
}

void NetworkServiceAsyncWaiter::DecodeContentEncoding(
    const ::blink::Vector<::network::mojom::blink::SourceType>& content_encoding_types, ::mojo::ScopedDataPipeConsumerHandle source_body, ::mojo::ScopedDataPipeProducerHandle dest_body, int32_t* out_error_code) {
  base::RunLoop loop;
  proxy_->DecodeContentEncoding(
      std::move(content_encoding_types),
      std::move(source_body),
      std::move(dest_body),
      base::BindOnce(
          [](base::RunLoop* loop,
             int32_t* out_error_code
,
             int32_t error_code) {*out_error_code = std::move(error_code);
            loop->Quit();
          },
          &loop,
          out_error_code));
  loop.Run();
}

int32_t NetworkServiceAsyncWaiter::DecodeContentEncoding(
    const ::blink::Vector<::network::mojom::blink::SourceType>& content_encoding_types, ::mojo::ScopedDataPipeConsumerHandle source_body, ::mojo::ScopedDataPipeProducerHandle dest_body) {
  int32_t async_wait_result;
  DecodeContentEncoding(std::move(content_encoding_types),std::move(source_body),std::move(dest_body),&async_wait_result);
  return async_wait_result;
}




