DurableMessageCollectorAsyncWaiter::DurableMessageCollectorAsyncWaiter(
    DurableMessageCollector* proxy) : proxy_(proxy) {}

DurableMessageCollectorAsyncWaiter::~DurableMessageCollectorAsyncWaiter() = default;


void DurableMessageCollectorAsyncWaiter::Configure(
    NetworkDurableMessageConfigPtr config) {
  base::RunLoop loop;
  proxy_->Configure(
      std::move(config),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}



void DurableMessageCollectorAsyncWaiter::EnableForProfile(
    const ::base::UnguessableToken& throttling_profile_id) {
  base::RunLoop loop;
  proxy_->EnableForProfile(
      std::move(throttling_profile_id),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}



void DurableMessageCollectorAsyncWaiter::DisableForProfile(
    const ::base::UnguessableToken& throttling_profile_id) {
  base::RunLoop loop;
  proxy_->DisableForProfile(
      std::move(throttling_profile_id),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}



void DurableMessageCollectorAsyncWaiter::Retrieve(
    const ::blink::String& devtools_request_id, ::mojo_base::mojom::blink::BigBufferPtr* out_message) {
  base::RunLoop loop;
  proxy_->Retrieve(
      std::move(devtools_request_id),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::mojo_base::mojom::blink::BigBufferPtr* out_message
,
             ::mojo_base::mojom::blink::BigBufferPtr message) {*out_message = std::move(message);
            loop->Quit();
          },
          &loop,
          out_message));
  loop.Run();
}

::mojo_base::mojom::blink::BigBufferPtr DurableMessageCollectorAsyncWaiter::Retrieve(
    const ::blink::String& devtools_request_id) {
  ::mojo_base::mojom::blink::BigBufferPtr async_wait_result;
  Retrieve(std::move(devtools_request_id),&async_wait_result);
  return async_wait_result;
}






